package org.example;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

public class Main {

    private static final BufferedReader INPUT =
            new BufferedReader(new InputStreamReader(System.in));

    private static String readLine(String message) throws IOException {
        System.out.print(message);
        System.out.flush();

        String line = INPUT.readLine();

        if (line == null) {
            throw new IOException("Поток ввода закрыт");
        }

        return line.trim();
    }

    // Чтение множества элементов через запятую
    private static Set<String> readSet(String message)
            throws IOException {

        String line = readLine(message);

        Set<String> result = new HashSet<>();

        for (String value : line.split(",")) {
            value = value.trim();

            if (!value.isEmpty()) {
                result.add(value);
            }
        }

        return result;
    }

    // Чтение алфавита
    private static Set<Character> readAlphabet(String message)
            throws IOException {

        Set<String> values = readSet(message);
        Set<Character> result = new HashSet<>();

        for (String value : values) {
            if (value.length() != 1) {
                throw new IllegalArgumentException(
                        "Элемент алфавита должен быть одним символом: "
                                + value);
            }

            result.add(value.charAt(0));
        }

        return result;
    }

    // Чтение перехода
    private static Transition readTransition(String line) {

        String[] sides = line.split("->", -1);

        if (sides.length != 2) {
            throw new IllegalArgumentException(
                    "Неверный формат перехода: " + line);
        }

        String[] left = sides[0].trim().split(",", -1);
        String[] right = sides[1].trim().split(",", -1);

        if (left.length != 3 || right.length != 2) {
            throw new IllegalArgumentException(
                    "Формат: q,a,Z -> q',gamma");
        }

        String currentState = left[0].trim();

        String input = left[1].trim();

        Character inputSymbol = isEmptySymbol(input)
                ? null
                : parseChar(input);

        char stackSymbol = parseChar(left[2].trim());

        String nextState = right[0].trim();

        String replacement = right[1].trim();

        if (isEmptySymbol(replacement)) {
            replacement = "";
        }

        return new Transition(
                currentState,
                inputSymbol,
                stackSymbol,
                nextState,
                replacement
        );
    }

    private static boolean isEmptySymbol(String value) {
        return value.isEmpty()
                || value.equalsIgnoreCase("lambda")
                || value.equals("#");
    }

    private static char parseChar(String value) {

        if (value.length() != 1) {
            throw new IllegalArgumentException(
                    "Ожидался один символ: " + value);
        }

        return value.charAt(0);
    }

    public static void main(String[] args) {

        System.out.println("========================================");
        System.out.println("       ДЕТЕРМИНИРОВАННЫЙ МП-АВТОМАТ");
        System.out.println("========================================\n");

        try {

            // 1. Ввод параметров автомата

            Set<String> states =
                    readSet("Состояния: ");

            Set<Character> inputAlphabet =
                    readAlphabet("Алфавит: ");

            Set<Character> stackAlphabet =
                    readAlphabet("Алфавит стека: ");

            String initialState =
                    readLine("Начальное состояние: ");

            char initialStackSymbol =
                    parseChar(readLine("Начальный символ стека: "));

            Set<String> finalStates =
                    readSet("Множество конечных состояний: ");

            // 2. Создание автомата

            PushdownAutomaton automaton =
                    new PushdownAutomaton(
                            states,
                            inputAlphabet,
                            stackAlphabet,
                            initialState,
                            initialStackSymbol,
                            finalStates
                    );

            // 3. Ввод функции переходов
            System.out.println("\nP = ("
                    + formatSet(states) + ", "
                    + formatCharSet(inputAlphabet) + ", "
                    + formatCharSet(stackAlphabet) + ", "
                    + "δ, "
                    + initialState + ", "
                    + initialStackSymbol + ", "
                    + formatSet(finalStates)
                    + ")");
            System.out.println("\nФункция переходов");
            System.out.println("Формат: q,a,Z -> q',gamma");
            System.out.println("Обозначения пустой строки:");
            System.out.println("  lambda — переход без чтения входного символа");
            System.out.println("  lambda — удаление верхнего символа стека");
            System.out.println("  # — альтернативное обозначение пустой строки");
            System.out.println("  Пустое значение также означает lambda.\n");

            int count = Integer.parseInt(
                    readLine("Количество переходов: "));

            for (int i = 0; i < count; i++) {

                String line = readLine("δ" + (i + 1) + ": ");

                Transition transition = readTransition(line);

                automaton.addTransition(transition);
            }

            // 4. Проверка цепочек

            System.out.println("\nПроверка цепочек");

            int chainsCount = Integer.parseInt(
                    readLine("Количество цепочек: "));

            for (int i = 0; i < chainsCount; i++) {

                String input = readLine(
                        "Цепочка " + (i + 1) + ": ");

                if (input.equals("lambda") || input.isEmpty()) {
                    input = "";
                }

                automaton.accepts(input);
            }

            System.out.println("\nПроверка завершена.");

        } catch (IOException | IllegalArgumentException e) {

            System.err.println("\nОшибка: " + e.getMessage());

        }
    }

    private static String formatSet(Set<String> values) {
        return "{" + String.join(", ", values) + "}";
    }

    private static String formatCharSet(Set<Character> values) {
        StringBuilder result = new StringBuilder("{");

        boolean first = true;

        for (Character value : values) {
            if (!first) {
                result.append(", ");
            }

            result.append(value);
            first = false;
        }

        return result.append("}").toString();
    }
}